# ---------- COMPUTADAS ----------
def hav(lat1,lon1,lat2,lon2):
    p=np.pi/180;a=np.sin((lat2-lat1)*p/2)**2+np.cos(lat1*p)*np.cos(lat2*p)*np.sin((lon2-lon1)*p/2)**2
    return 12742*np.arcsin(np.sqrt(a))
u["lat"]=u.lugar.map(lambda x:co[x][0]);u["lon"]=u.lugar.map(lambda x:co[x][1])
u["dba"]=hav(u.lat,u.lon,-34.6,-58.38)
u["short"]=u.lugar.map(short)
cats={}
def add(name,desc,mask,kind): cats[name]=(desc,set(u.index[mask]),kind)
for n,(desc,m) in PL.items(): add(n,desc,u.short.isin(m),"lugar")
for n,(desc,m) in PA.items(): add(n,desc,u.pais.isin(m),"pais")
add("Hemisferio sur","Latitud menor a 0",u.lat<0,"calculada")
add("Hemisferio norte","Latitud mayor o igual a 0",u.lat>=0,"calculada")
add("Zona tropical (|lat| < 23,5)","Entre los tropicos",u.lat.abs()<23.5,"calculada")
add("Latitud templada (23,5 a 50)","Entre tropicos y 50 grados",(u.lat.abs()>=23.5)&(u.lat.abs()<50),"calculada")
add("Latitud alta (> 50)","Mas de 50 grados de latitud",u.lat.abs()>=50,"calculada")
add("Cerca de Buenos Aires (< 4.000 km)","Distancia a Buenos Aires menor a 4000 km",u.dba<4000,"calculada")
add("Lejos de Buenos Aires (> 12.000 km)","Distancia a Buenos Aires mayor a 12000 km",u.dba>12000,"calculada")
add("Antipodas de Argentina (> 15.000 km)","Mas de 15000 km de Buenos Aires",u.dba>15000,"calculada")
add("Oeste de Greenwich","Longitud menor a 0",u.lon<0,"calculada")
add("Este lejano (lon > 100)","Longitud mayor a 100 E",u.lon>100,"calculada")
add("Husos adelantados 6+ hs vs Argentina (lon > 60 E)","Aprox. 9 horas o mas adelante de Argentina",u.lon>60,"calculada")
# complementos
add("Ciudad interior (no costera)","Complemento de ciudad costera",~u.short.isin(PL["Ciudad costera"][1]),"complemento")
add("No capital nacional","Complemento de capital nacional",~u.short.isin(PL["Capital nacional"][1]),"complemento")
add("Ciudad grande o mediana (no pueblo)","Complemento de pueblo",~u.short.isin(PL["Pueblo o ciudad chica (menos de ~150 mil)"][1]),"complemento")
# regiones del analisis previo como referencia no se repiten
rows=[]
for n,(desc,idx,kind) in cats.items():
    sub=u.loc[list(idx)]
    rows.append((n,kind,desc,len(idx),sub.lugar.nunique(),sorted(sub.lugar.unique())))
rows.sort(key=lambda r:-r[3])
tot=len(u)
def nivel(n): return "BUENA" if n>=60 else "OK" if n>=35 else "JUSTA" if n>=20 else "CHICA"
out=["# MapTap - Categorias para analizar rendimiento por agregadores no obvios\n",
f"Base: {tot} rondas (22/7 al 18/10/2026, Challenge excluido), {u.lugar.nunique()} lugares distintos. Muestra: BUENA >= 60 rondas, OK 35-59, JUSTA 20-34, CHICA < 20.\n",
"Tipo: lugar = lista manual por lugar; pais = lista manual por pais; calculada = sale de latitud, longitud y distancia a Buenos Aires; complemento = todo lo que no esta en otra categoria.\n",
"Las listas manuales son criterio mio; si una pertenencia no te cierra se corrige en maptap-categorias-lugares.csv y se recalcula.\n",
"## Resumen\n","| Categoria | Tipo | Rondas | Lugares | Muestra |","|---|---|---:|---:|---|"]
for n,k,dsc,r,l,_ in rows: out.append(f"| {n} | {k} | {r} | {l} | {nivel(r)} |")
out.append("\n## Detalle\n")
for n,k,dsc,r,l,ls in rows:
    out.append(f"### {n}\n\n{dsc}. Rondas: {r}. Lugares: {l}. Muestra: {nivel(r)}.\n\nLugares: "+"; ".join(x.split(',')[0] if k!='pais' else x for x in ls)+"\n")
open(D+"informes/maptap-categorias.md","w",encoding="utf8").write("\n".join(out))
